-- Seed the platforms that were hard-coded on the site so they can be edited from the admin screen.
-- Skipped for any slug that already exists. Logos point at the files served by the site itself.
ON CONFLICT ("slug") DO NOTHING;

-- Elefin: the partner code lives in the link path, so the link must be exactly this one.
UPDATE "Platform" SET "referralUrl" = 'https://partners.elefin.com/go/WCAM-ETK5U8', "referralCode" = 'ETK5U8' WHERE "slug" = 'elefin';
